-- 2) Copia a tabela vigente para cada empresa (IPLAMM, KRATOS e as que existirem).
insert into public.log_piso_coef (empresa_id, tabela, tipo_carga, eixos, ccd, cc, vigencia, fonte)
select e.id, a.tabela, a.tipo_carga, a.eixos, a.ccd, a.cc, a.vigencia, a.fonte
  from public.empresas e cross join public.antt_piso_coef a
 where a.vigencia = date '2026-09-30'
on conflict (empresa_id, tabela, tipo_carga, eixos, vigencia) do nothing;

-- 3) Empresa nova já nasce com a tabela ANTT mais recente.
create or replace function public._piso_padrao_empresa() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.log_piso_coef (empresa_id, tabela, tipo_carga, eixos, ccd, cc, vigencia, fonte)
  select new.id, a.tabela, a.tipo_carga, a.eixos, a.ccd, a.cc, a.vigencia, a.fonte
    from public.antt_piso_coef a
   where a.vigencia = (select max(vigencia) from public.antt_piso_coef)
  on conflict (empresa_id, tabela, tipo_carga, eixos, vigencia) do nothing;
  return new;
end $$;
revoke all on function public._piso_padrao_empresa() from public, anon, authenticated;
drop trigger if exists empresas_piso_padrao on public.empresas;
create trigger empresas_piso_padrao after insert on public.empresas for each row execute function public._piso_padrao_empresa();

